    "bt.heading": "Was heißt das für die Maschine?",
    "bt.sub": "Dieselben Werkstoffe wie oben — hier steht, wo sie in der Maschine sitzen. Welche Werkstoffe konkret verbaut sind, steht in der Betriebsanleitung oder der Ersatzteilliste.",
    "bt.caution": "· mit Vorsicht",
    "bt.unsuitable": "· besser meiden",
    "bt.generalHeading": "Bauteile, die bei jedem wassermischbaren KSS zu beachten sind",
    "bt.sichtscheibe.title": "Sichtscheibe aus Polycarbonat — sicherheitsrelevant",
    "bt.sichtscheibe.text": "Kühlschmierstoff lässt Polycarbonat verspröden, und zwar unsichtbar: Die Scheibe sieht unverändert aus, hält einen wegfliegenden Span aber nicht mehr auf. Gemessen wurden −40 % Rückhaltevermögen nach neun Monaten und nur noch 20 % nach zehn Jahren bei ungeschützten Scheiben. Der VDW nennt als Austauschfrist zwei Jahre für ungeschützte und zwölf Jahre für geschützte Scheiben — die verbindliche Frist steht in deiner Betriebsanleitung, das Herstelljahr auf der Plakette an der Scheibe.",
    "bt.sichtscheibe.source": "Quelle: DGUV/BGHM FBHM-040 „Schutzscheiben an Werkzeugmaschinen“, VDW-Empfehlung.",
    "bt.zink.title": "Verzinkte Leitungen und Behälter",
    "bt.zink.text": "Wassermischbare Konzentrate greifen Zink an; Beschichtungen im Tank können sich ablösen. Für Leitungen, Behälter und Auffangwannen deshalb kein verzinktes Material verwenden. Auch ein Chloridgehalt über 30 mg/l im Ansetzwasser führt zu Korrosion an der Maschine.",
    "bt.zink.source": "Quelle: FUCHS, Anwendungshinweise zu wassermischbaren Kühlschmierstoffen.",
