    "pdf.disclaimer": "Hinweis: Die hier abrufbaren Dokumente (PDF) stammen aus öffentlich zugänglichen Quellen im Internet (z. B. Hersteller- und Händlerseiten) und werden unverändert als Service wiedergegeben. Maßgeblich ist allein das jeweils aktuelle Originaldokument des Herstellers bzw. Lieferanten. Für Richtigkeit, Vollständigkeit und Aktualität übernehmen wir keine Gewähr; eine Haftung hierfür ist — soweit gesetzlich zulässig — ausgeschlossen. Sicherheitsrelevante Angaben bitte stets anhand des aktuellen Sicherheitsdatenblatts Ihres Lieferanten prüfen.",
