    "advisor.greeting": "Hallo! Ich bin dein Brisco-Berater. Beschreib mir dein Problem oder deine Aufgabe in normalen Worten — z. B. „Mein Kühlschmierstoff schäumt“ oder „Ich fräse Aluminium und suche eine Emulsion“. Ich zeige dir passende Produkte, Angebote und Praxis-Wissen.",
