    // Vertrauensseite (/vertrauen)
    "trust.title": "So sorgen wir für Vertrauen",
    "trust.intro1a": "Beim Handel unter Unternehmen zählen zwei Fragen: ",
    "trust.introQ1": "Mit wem habe ich es zu tun?",
    "trust.intro1b": " Und: ",
    "trust.introQ2": "Bin ich abgesichert, wenn etwas schiefgeht?",
    "trust.intro2": "Auf beides gibt Brisco eine klare Antwort. Hier erfährst du, wie.",
    "trust.tiersTitle": "Verifizierungsstufen",
    "trust.tiersText": "Jeder Reseller trägt eine Vertrauensstufe. Sie steigt mit geprüfter Identität, abgeschlossenen Geschäften und guten Bewertungen — und ist überall sichtbar.",
    "trust.reviewsTitle": "Bewertungen, die man nicht kaufen kann",
    "trust.reviewsText": "Eine Bewertung abgeben darf nur, wer über Brisco wirklich ein Geschäft abgeschlossen hat. Jeder Stern hängt an einer echten Transaktion — keine gekauften, keine erfundenen. Schnitt und Anzahl stehen offen auf jedem Profil.",
    "trust.pseudoTitle": "Anonym handeln, neutral sortiert",
    "trust.pseudoText1": "Du trittst unter einem Pseudonym auf — dein Klarname bleibt verborgen. In den Nachrichten hält ein automatischer Filter Kontaktdaten (E-Mail, Telefon, Links) zurück, damit dich niemand an der Plattform vorbei abwirbt.",
    "trust.pseudoText2a": "Und die Reihenfolge ist ehrlich: Bezahlte Platzierungen sind für alle sichtbar als ",
    "trust.pseudoSponsored": "„Gesponsert“",
    "trust.pseudoText2b": " gekennzeichnet. Alles andere ist neutral sortiert.",
    "trust.docsTitle": "Alles dokumentiert",
    "trust.docsTextA": "Anfrage, Angebot, Annahme und Nachrichten laufen nachvollziehbar über die Plattform — nicht in verstreuten E-Mails. Geht etwas schief, gibt es einen klaren Weg zur Reklamation. Die Spielregeln stehen in den ",
    "trust.protTitle": "Käuferschutz: bezahlen, ohne in Vorleistung zu gehen",
    "trust.protIntro": "Ein Fass Hydrauliköl kostet schnell vierstellig, ein IBC oder eine Palette deutlich mehr. Wer bei einem unbekannten Händler zuerst überweist, trägt das ganze Risiko allein — und wer zuerst liefert, ebenso. Genau diese Pattsituation löst der Käuferschutz auf.",
    "trust.howItWorks": "So läuft es ab",
    "trust.step1t": "Du zahlst — aber nicht an den Verkäufer",
    "trust.step1d": "Der Betrag geht per Karte an den Zahlungsdienstleister Stripe und bleibt dort liegen. Der Verkäufer sieht, dass gezahlt wurde, bekommt aber keinen Cent.",
    "trust.step2t": "Der Verkäufer liefert",
    "trust.step2d": "Er liefert in dem Wissen, dass das Geld bereits hinterlegt ist. Deshalb liefert er auch an Käufer, die er nicht kennt.",
    "trust.step3t": "Du bestätigst den Erhalt",
    "trust.step3d": "Erst dieser Klick gibt das Geld frei. Ohne ihn bewegt sich nichts — auch nicht durch den Verkäufer.",
    "trust.step4t": "Stimmt etwas nicht: „Problem melden“",
    "trust.step4d": "Statt freizugeben, meldest du das Problem. Brisco prüft und entscheidet über Freigabe oder Rückerstattung.",
    "trust.benefitsTitle": "Was du davon hast",
    "trust.ben1t": "Keine Vorkasse an einen Fremden.",
    "trust.ben1d": " Dein Geld liegt bei Stripe, nicht beim Verkäufer.",
    "trust.ben2t": "Du hältst den Schlüssel.",
    "trust.ben2d": " Ohne deine Lieferbestätigung wird nichts ausgezahlt.",
    "trust.ben3t": "Bei Rückerstattung bekommst du alles zurück — auch die Gebühr.",
    "trust.ben3d": " Ein Problemfall darf dich nichts kosten.",
    "trust.ben4t": "Handel mit Unbekannten wird möglich.",
    "trust.ben4d": " Der beste Preis kommt oft von einem Händler, mit dem du noch nie zu tun hattest.",
    "trust.ben5t": "Alles dokumentiert.",
    "trust.ben5d": " Angebot, Annahme, Zahlung und Lieferung liegen nachvollziehbar auf der Plattform — nicht in verstreuten E-Mails.",
    "trust.costTitle": "Was es kostet",
    "trust.costText": "vom Kaufbetrag, getragen vom Käufer. Bei 2.000 € sind das 50,25 €. Die Gebühr deckt die Zahlungsabwicklung und den Käuferschutz-Service; ein Teil bleibt als Entgelt bei Brisco. Wird dir erstattet, bekommst du auch diese Gebühr zurück.",
    "trust.limitsTitle": "Was der Käuferschutz nicht ist — damit du dich richtig entscheidest",
    "trust.lim1t": "Wir verwahren kein Geld auf einem eigenen Konto und bieten keine Versicherung.",
    "trust.lim1d": " Brisco ist keine Bank. Der Betrag wird beim regulierten Zahlungsdienstleister Stripe gehalten, nicht auf einem Konto von Brisco.",
    "trust.lim2t": "Im Streitfall entscheidet Brisco",
    "trust.lim2d": " — nach Aktenlage, nicht als Gericht. Der Rechtsweg bleibt dir unbenommen.",
    "trust.lim3t": "Nicht bei jedem Anbieter verfügbar.",
    "trust.lim3d": " Nur wer das Abzeichen „Käuferschutz verfügbar“ trägt, hat die Auszahlung eingerichtet.",
    "trust.lim4t": "Er ersetzt keine Wareneingangsprüfung.",
    "trust.lim4d": " Bestätige die Lieferung erst, wenn du geprüft hast — danach ist das Geld beim Verkäufer.",
    "trust.contractNote": "Die vertraglichen Einzelheiten stehen in ",
    "trust.contractLink": "§ 7 der AGB",
