    // Mitgliedschaft (/mitgliedschaft)
    "mem.title": "Mitgliedschaft & Kosten",
    "mem.lead": "Brisco finanziert sich über Mitgliedschaften — nicht über Provisionen auf deine Geschäfte. Was du hier abschließt, ist ein Jahres-Zugang; die KI-Funktionen laufen über Credits. Beides ist unabhängig voneinander kündbar. Wickelst du eine Zahlung freiwillig über die Plattform ab, fällt darauf eine kleine Gebühr an — sonst nicht.",
    "mem.status": "Status",
    "mem.activeUntil": "Abo aktiv bis {d}",
    "mem.trialUntil": "Kennenlernphase bis {d}",
    "mem.noAccess": "Kein aktiver Zugang",
    "mem.renewalReminder": "Erinnerung: Dein Abo verlängert sich in weniger als 30 Tagen automatisch.",
    "mem.tiersLine": "Der Jahres-Zugang gibt es in drei Stufen — Basis {b} €, Pro {pr} € und Marke {m} € — jeweils für 12 Monate.",
    "mem.trialSuffix": " Während der Kennenlernphase kannst du alles ohne Abo ausprobieren.",
    "mem.contractTitle": "Vertragslaufzeit & Kündigung",
    "mem.contract1": "Laufzeit 12 Monate, danach automatische Verlängerung um jeweils 12 Monate.",
    "mem.contract2": "Kündigung jederzeit möglich, ohne Vorlauffrist — über den Knopf „Abo kündigen“ oben auf dieser Seite. Der Zugang bleibt bis zum Ende der bereits bezahlten Periode aktiv, danach erfolgt keine weitere Abbuchung.",
    "mem.contract3": "Zahlungsmethode: Karte, Wallets und weitere über Stripe, jährliche Abbuchung.",
    "mem.contract4": "KI-Credits sind ein separates Guthaben (Prepaid, kein Abo) — siehe Preisliste unten.",
    "mem.creditsTitle": "KI-Credits",
    "mem.creditsWord": "Credits",
    "mem.creditsCost": "KI-Funktionen kosten Credits: Berater-Frage und KSS-Wizard je {c1} Credit, KI-Alternativen {c2} Credit, Web-Recherche {c3} Credits. 1 Credit = {price}.",
    "mem.recentBookings": "Letzte Buchungen",
    "mem.storefrontTitle": "Marken-Schaufenster",
    "mem.storefrontText": "Als Marke-Mitglied vertrittst du einen Hersteller offiziell: Die Herstellerseite wird zum verifizierten Schaufenster und deine Produkte werden im KSS-Wizard gekennzeichnet hervorgehoben.",
    "mem.adsManage": "Werbeanzeigen schalten & verwalten →",
    "mem.protectionTitle": "Käuferschutz anbieten",
    "mem.protectionText": "Freiwillig, nicht Pflicht: Wer will, lässt die Zahlung über die Plattform laufen — das Geld wird geparkt und nach der Lieferbestätigung an dich freigegeben. Nur dann fällt eine kleine Gebühr an (2,5 % + 0,25 €, getragen vom Käufer). Wer direkt abwickelt, zahlt keine Provision.",
    "mem.redeemTitle": "Gutschein-Code einlösen",
    "mem.redeemText": "Hast du einen Code von Brisco erhalten? Hier einlösen für zusätzliche Credits.",
    "mem.referralTitle": "Kunden werben — {n} Credits pro Neukunde",
    "mem.referralText": "Lade einen Kontakt per E-Mail ein oder teile deinen Empfehlungs-Link. Registriert sich darüber ein Neukunde, bekommst du {n} Credits gutgeschrieben.",
    "mem.payTitle": "Sichere Bezahlung über Stripe",
    "mem.payText1": "Die Zahlung läuft über Stripe, einen weltweit führenden Zahlungsdienstleister. Ihre Zahlungsdaten werden verschlüsselt direkt bei Stripe verarbeitet und ",
    "mem.payTextBold": "niemals auf dieser Plattform gespeichert",
    "mem.payText2": " (Sicherheitsstandard PCI-DSS Level 1).",
