    "ads.lockTitle": "Werbeanzeigen sind Teil der Stufe Marke",
    "ads.lockBody": "Als Marke-Mitglied schaltest du eigene Banner an den Werbeplätzen der Plattform (Startseite, Marken-Schaufenster, Angebotsübersicht) — mit eigenem Bild, Text, Link und Laufzeit.",
    "ads.switchToMarke": "Auf Marke wechseln",
    "ads.introBase": "Schalte Banner an den Werbeplätzen der Plattform. Anzeigen erscheinen klar als „Anzeige“ gekennzeichnet",
    "ads.introLinkedPre": "und sind mit Ihrer Marke",
    "ads.introLinkedPost": " verknüpft.",
    "ads.introTip": "Tipp: Hinterlege unter „Mitgliedschaft“ deine Marke, damit die Schaufenster-Platzierung greift.",
    "ghs.back": "Zurück zum Praxis-Wissen",
    "ghs.subtitle": "Die 9 offiziellen Warnrauten auf Etikett und Sicherheitsdatenblatt — einfach erklärt",
    "ghs.introBefore": "Diese Symbole sind EU-weit vorgeschrieben (CLP-Verordnung, Teil des REACH-Regelwerks). Sie stehen auf jedem Gebinde und in",
    "ghs.introAfter": "Auf unseren Produktseiten siehst du sie direkt im SDS-Kärtchen — so erkennst du auf einen Blick, worauf beim Umgang zu achten ist.",
    "ghs.hSatze": "H-Sätze:",
    "ghs.countSingular": "In {count} Sicherheitsdatenblatt unseres Bestands",
    "ghs.countPlural": "In {count} Sicherheitsdatenblättern unseres Bestands",
    "ghs.countNone": "In unserem Bestand aktuell nicht vertreten",
    "ghs.footnote1": "Hinweis: Kurzerklärungen ohne Anspruch auf Vollständigkeit — verbindlich sind Etikett und Sicherheitsdatenblatt des jeweiligen Produkts. Signalwörter:",
    "ghs.signalDanger": "„Gefahr“",
    "ghs.footnoteMid": "(schwerwiegender) bzw.",
    "ghs.signalWarning": "„Achtung“",
    "ghs.footnoteEnd": "(weniger schwerwiegend).",
    "ghs.s.GHS01.name": "Explosiv",
    "ghs.s.GHS01.meaning": "Stoff kann explodieren — durch Schlag, Reibung, Funken oder Hitze.",
    "ghs.s.GHS01.praxis": "Bei Ölen und Kühlschmierstoffen praktisch nie anzutreffen; relevant nur für Spezialchemie.",
    "ghs.s.GHS02.name": "Entzündbar",
    "ghs.s.GHS02.meaning": "Fängt leicht Feuer — schon Funken oder heiße Flächen genügen.",
    "ghs.s.GHS02.praxis": "Wichtig bei Reinigern, Verdünnern und Schneidölen mit niedrigem Flammpunkt. Auf den Flammpunkt im SDS achten.",
    "ghs.s.GHS03.name": "Brandfördernd (oxidierend)",
    "ghs.s.GHS03.meaning": "Brennt selbst nicht, facht aber Brände stark an — liefert Sauerstoff.",
    "ghs.s.GHS03.praxis": "Bei Schmierstoffen selten; eher bei Wasserbehandlungs-Chemie.",
    "ghs.s.GHS04.name": "Gase unter Druck",
    "ghs.s.GHS04.meaning": "Verdichtetes oder verflüssigtes Gas — Behälter kann bersten oder Kälteverbrennungen verursachen.",
    "ghs.s.GHS04.praxis": "Betrifft Sprays/Aerosole, z. B. Schmierstoff- und Rostlöser-Sprays.",
    "ghs.s.GHS05.name": "Ätzend / korrosiv",
    "ghs.s.GHS05.meaning": "Zerstört Haut und Augen bei Kontakt; greift auch Metalle an.",
    "ghs.s.GHS05.praxis": "Vorsicht bei KSS-Konzentraten und Systemreinigern — beim Ansetzen Handschuhe und Schutzbrille tragen.",
    "ghs.s.GHS06.name": "Giftig (akut toxisch)",
    "ghs.s.GHS06.meaning": "Schon kleine Mengen können beim Einatmen, Verschlucken oder Hautkontakt schwer schaden.",
    "ghs.s.GHS06.praxis": "Bei modernen KSS und Ölen sehr selten — taucht es auf, das Produkt besonders sorgfältig handhaben.",
    "ghs.s.GHS07.name": "Reizend / gesundheitsschädlich",
    "ghs.s.GHS07.meaning": "Reizt Haut, Augen oder Atemwege; kann Allergien auslösen. Die mildeste Warnstufe.",
    "ghs.s.GHS07.praxis": "Das häufigste Symbol bei Kühlschmierstoffen — typisch wegen Hautreizung (H315) oder Sensibilisierung (H317). Hautkontakt minimieren, Pflegeplan beachten.",
    "ghs.s.GHS08.name": "Gesundheitsgefahr (langfristig)",
    "ghs.s.GHS08.meaning": "Kann Organe schädigen, Krebs erzeugen oder die Fruchtbarkeit beeinträchtigen — oft erst bei längerem Kontakt.",
    "ghs.s.GHS08.praxis": "Achtung bei Produkten mit H304 (kann beim Verschlucken in die Lunge gelangen) — klassisch bei dünnflüssigen Ölen. Auch für TRGS-611-Themen (Nitrosamine) relevant.",
    "ghs.s.GHS09.name": "Umweltgefährlich",
    "ghs.s.GHS09.meaning": "Giftig für Fische und andere Wasserorganismen — darf nicht in Gewässer oder Kanalisation gelangen.",
    "ghs.s.GHS09.praxis": "Wichtig für Lagerung (Auffangwanne!) und Entsorgung: gebrauchte Emulsion und Öl immer als Sonderabfall entsorgen.",
