    "tank.labelTitle": "Label with QR code",
    "tank.labelText": "Download the sheet as a PDF, cut out the labels and stick one on the tank. Scanning it opens the measurement form for exactly this tank — no searching, no sign-in. The label also carries the product, target concentration and refractometer factor.",
    "tank.labelDownload": "Download labels as PDF (4 up)",
