    "mix.title": "Mixing calculator — what goes in?",
    "mix.intro": "Tell the page how much is missing and what you measured. It works out how much water and how much concentrate belong in the tank.",
    "mix.fVolume": "Total tank volume (litres)",
    "mix.fTarget": "Target concentration (%)",
    "mix.fTargetHint": "Manufacturer recommends {min}–{max} %",
    "mix.fMissing": "Missing volume (litres)",
    "mix.fCurrent": "Measured concentration (%)",
    "mix.water": "Water",
    "mix.concentrate": "Concentrate",
    "mix.resultLine": "That is a top-up mixture of {nachfuell} %. The tank then sits at a calculated {ergebnis} %.",
    "mix.waterFirst": "Always add the water first, then the concentrate — never the other way round.",
    "mix.tooLeanTitle": "The target cannot be reached this way",
    "mix.tooLeanText": "Even pure concentrate in the missing volume only brings the tank to {maximal} %. So top up with ready-mixed emulsion instead of water — around {empfehlung} %. If needed, in two steps with a measurement in between.",
    "mix.tooRichText": "The tank is already richer than the target (a calculated {maximal} % after topping up). Top up with water only and measure again afterwards.",
    "mix.badInput": "Please fill in all four fields plausibly: the missing volume cannot exceed the tank, and concentrations lie between 0 and 30 %.",
    "bt.heading": "What this means for the machine",
    "bt.sub": "The same materials as above — here is where they sit in the machine. Which materials are actually fitted is stated in the operating manual or the spare parts list.",
    "bt.caution": "· handle with care",
    "bt.unsuitable": "· better avoided",
    "bt.generalHeading": "Components to watch with any water-miscible coolant",
    "bt.sichtscheibe.title": "Polycarbonate viewing window — safety-relevant",
    "bt.sichtscheibe.text": "Coolant makes polycarbonate go brittle, and it does so invisibly: the window looks unchanged but no longer stops a flying chip. Measurements show −40 % retention capability after nine months and only 20 % after ten years for unprotected windows. The VDW gives replacement intervals of two years unprotected and twelve years protected — the binding interval is in your operating manual, the year of manufacture on the plate at the window.",
    "bt.sichtscheibe.source": "Source: DGUV/BGHM FBHM-040 on protective windows for machine tools, VDW recommendation.",
    "bt.zink.title": "Galvanised pipes and tanks",
    "bt.zink.text": "Water-miscible concentrates attack zinc, and coatings inside the tank can come off. So do not use galvanised material for pipes, tanks or drip trays. A chloride content above 30 mg/l in the make-up water also causes corrosion on the machine.",
    "bt.zink.source": "Source: FUCHS, application notes on water-miscible coolants.",
