    // Trust page (/vertrauen)
    "trust.title": "How we build trust",
    "trust.intro1a": "In business-to-business trade, two questions matter: ",
    "trust.introQ1": "Who am I dealing with?",
    "trust.intro1b": " And: ",
    "trust.introQ2": "Am I protected if something goes wrong?",
    "trust.intro2": "Brisco has a clear answer to both. Here's how.",
    "trust.tiersTitle": "Verification levels",
    "trust.tiersText": "Every reseller carries a trust level. It rises with verified identity, completed deals and good reviews — and is visible everywhere.",
    "trust.reviewsTitle": "Reviews you can't buy",
    "trust.reviewsText": "Only someone who has actually completed a deal via Brisco can leave a review. Every star is tied to a real transaction — none bought, none invented. Average and count are shown openly on each profile.",
    "trust.pseudoTitle": "Trade anonymously, sorted neutrally",
    "trust.pseudoText1": "You appear under an alias — your real name stays hidden. In messages, an automatic filter holds back contact details (email, phone, links) so no one can poach you off the platform.",
    "trust.pseudoText2a": "And the order is honest: paid placements are visibly marked as ",
    "trust.pseudoSponsored": "“Sponsored”",
    "trust.pseudoText2b": " for everyone. Everything else is sorted neutrally.",
    "trust.docsTitle": "Everything documented",
    "trust.docsTextA": "Request, offer, acceptance and messages run traceably through the platform — not in scattered emails. If something goes wrong, there is a clear path to complain. The rules are in the ",
    "trust.protTitle": "Buyer protection: pay without going first",
    "trust.protIntro": "A drum of hydraulic oil quickly runs into four figures, an IBC or a pallet much more. Whoever transfers first to an unknown dealer bears all the risk — and whoever ships first, too. Buyer protection resolves exactly this stand-off.",
    "trust.howItWorks": "How it works",
    "trust.step1t": "You pay — but not the seller",
    "trust.step1d": "The amount goes by card to the payment provider Stripe and stays there. The seller sees that payment was made but receives not a cent.",
    "trust.step2t": "The seller ships",
    "trust.step2d": "They ship knowing the money is already held. That's why they'll ship even to buyers they don't know.",
    "trust.step3t": "You confirm receipt",
    "trust.step3d": "Only this click releases the money. Without it, nothing moves — not even by the seller.",
    "trust.step4t": "Something wrong? “Report a problem”",
    "trust.step4d": "Instead of releasing, you report the problem. Brisco reviews it and decides on release or refund.",
    "trust.benefitsTitle": "What's in it for you",
    "trust.ben1t": "No prepayment to a stranger.",
    "trust.ben1d": " Your money sits with Stripe, not the seller.",
    "trust.ben2t": "You hold the key.",
    "trust.ben2d": " Nothing is paid out without your delivery confirmation.",
    "trust.ben3t": "On a refund you get everything back — including the fee.",
    "trust.ben3d": " A problem case must not cost you anything.",
    "trust.ben4t": "Trading with unknowns becomes possible.",
    "trust.ben4d": " The best price often comes from a dealer you've never worked with.",
    "trust.ben5t": "Everything documented.",
    "trust.ben5d": " Offer, acceptance, payment and delivery are traceable on the platform — not in scattered emails.",
    "trust.costTitle": "What it costs",
    "trust.costText": "of the purchase amount, borne by the buyer. On €2,000 that's €50.25. The fee covers payment processing and the buyer-protection service; part of it remains as remuneration for Brisco. If you're refunded, you get this fee back too.",
    "trust.limitsTitle": "What buyer protection is not — so you decide correctly",
    "trust.lim1t": "Not an escrow account and not insurance.",
    "trust.lim1d": " Brisco is not a bank. The amount is held at the regulated payment provider Stripe, not in a Brisco account.",
    "trust.lim2t": "In a dispute, Brisco decides",
    "trust.lim2d": " — on the evidence, not as a court. Your legal remedies remain available.",
    "trust.lim3t": "Not available with every supplier.",
    "trust.lim3d": " Only those carrying the “Buyer protection available” badge have set up the payout.",
    "trust.lim4t": "It does not replace an incoming-goods check.",
    "trust.lim4d": " Confirm delivery only after you've checked — after that the money is with the seller.",
    "trust.contractNote": "The contractual details are in ",
    "trust.contractLink": "§ 7 of the Terms",
