    "ads.lockTitle": "Ads are part of the Brand tier",
    "ads.lockBody": "As a Brand member you place your own banners in the platform's ad slots (home page, brand storefront, offers overview) — with your own image, text, link and duration.",
    "ads.switchToMarke": "Switch to Brand",
    "ads.introBase": "Place banners in the platform's ad slots. Ads are clearly marked as “advertisement”",
    "ads.introLinkedPre": "and are linked to your brand",
    "ads.introLinkedPost": ".",
    "ads.introTip": "Tip: add your brand under “Membership” so the storefront placement takes effect.",
    "ghs.back": "Back to practical knowledge",
    "ghs.subtitle": "The 9 official hazard diamonds on the label and safety data sheet — explained simply",
    "ghs.introBefore": "These symbols are mandatory across the EU (CLP Regulation, part of the REACH framework). They appear on every container and in",
    "ghs.introAfter": "On our product pages you see them directly in the SDS card — so you can tell at a glance what to watch out for when handling.",
    "ghs.hSatze": "H-statements:",
    "ghs.countSingular": "In {count} safety data sheet in our stock",
    "ghs.countPlural": "In {count} safety data sheets in our stock",
    "ghs.countNone": "Currently not present in our stock",
    "ghs.footnote1": "Note: brief explanations with no claim to completeness — the label and safety data sheet of the respective product are binding. Signal words:",
    "ghs.signalDanger": "“Danger”",
    "ghs.footnoteMid": "(more severe) or",
    "ghs.signalWarning": "“Warning”",
    "ghs.footnoteEnd": "(less severe).",
    "ghs.s.GHS01.name": "Explosive",
    "ghs.s.GHS01.meaning": "The substance can explode — from impact, friction, sparks or heat.",
    "ghs.s.GHS01.praxis": "Practically never seen with oils and coolants; relevant only for specialty chemicals.",
    "ghs.s.GHS02.name": "Flammable",
    "ghs.s.GHS02.meaning": "Catches fire easily — sparks or hot surfaces are enough.",
    "ghs.s.GHS02.praxis": "Important for cleaners, thinners and cutting oils with a low flash point. Check the flash point in the SDS.",
    "ghs.s.GHS03.name": "Oxidising (fire-intensifying)",
    "ghs.s.GHS03.meaning": "Does not burn itself but strongly intensifies fires — supplies oxygen.",
    "ghs.s.GHS03.praxis": "Rare with lubricants; more common in water-treatment chemistry.",
    "ghs.s.GHS04.name": "Gases under pressure",
    "ghs.s.GHS04.meaning": "Compressed or liquefied gas — the container can burst or cause cryogenic burns.",
    "ghs.s.GHS04.praxis": "Affects sprays/aerosols, e.g. lubricant and rust-remover sprays.",
    "ghs.s.GHS05.name": "Corrosive",
    "ghs.s.GHS05.meaning": "Destroys skin and eyes on contact; also attacks metals.",
    "ghs.s.GHS05.praxis": "Take care with coolant concentrates and system cleaners — wear gloves and safety goggles when mixing.",
    "ghs.s.GHS06.name": "Toxic (acutely toxic)",
    "ghs.s.GHS06.meaning": "Even small amounts can cause serious harm when inhaled, swallowed or in contact with skin.",
    "ghs.s.GHS06.praxis": "Very rare with modern coolants and oils — if it appears, handle the product with particular care.",
    "ghs.s.GHS07.name": "Irritant / harmful",
    "ghs.s.GHS07.meaning": "Irritates skin, eyes or airways; can trigger allergies. The mildest warning level.",
    "ghs.s.GHS07.praxis": "The most common symbol on coolants — typically due to skin irritation (H315) or sensitisation (H317). Minimise skin contact and follow the maintenance plan.",
    "ghs.s.GHS08.name": "Health hazard (long-term)",
    "ghs.s.GHS08.meaning": "Can damage organs, cause cancer or impair fertility — often only after prolonged contact.",
    "ghs.s.GHS08.praxis": "Watch out for products with H304 (can enter the lungs if swallowed) — typical of thin, low-viscosity oils. Also relevant for TRGS 611 topics (nitrosamines).",
    "ghs.s.GHS09.name": "Hazardous to the environment",
    "ghs.s.GHS09.meaning": "Toxic to fish and other aquatic organisms — must not enter waterways or drains.",
    "ghs.s.GHS09.praxis": "Important for storage (spill tray!) and disposal: always dispose of used emulsion and oil as hazardous waste.",
