    "mix.tooLeanText": "Zelfs zuiver concentraat in het ontbrekende volume brengt de tank maar op {maximal} %. Vul daarom niet met water bij, maar met kant-en-klare emulsie — ongeveer {empfehlung} %. Zo nodig in twee stappen met een meting ertussen.",
