    "mix.badInput": "Vul alle vier de velden plausibel in: het ontbrekende volume kan niet groter zijn dan de tank, en de concentraties liggen tussen 0 en 30 %.",
    "bt.heading": "Wat betekent dit voor de machine?",
    "bt.sub": "Dezelfde materialen als hierboven — hier staat waar ze in de machine zitten. Welke materialen daadwerkelijk zijn gemonteerd, staat in de handleiding of de onderdelenlijst.",
    "bt.caution": "· voorzichtig",
    "bt.unsuitable": "· beter vermijden",
    "bt.generalHeading": "Onderdelen om op te letten bij elk watermengbaar koelsmeermiddel",
    "bt.sichtscheibe.title": "Kijkvenster van polycarbonaat — veiligheidsrelevant",
    "bt.sichtscheibe.text": "Koelsmeermiddel maakt polycarbonaat bros, en wel onzichtbaar: het venster ziet er onveranderd uit, maar houdt een wegvliegende spaan niet meer tegen. Gemeten is −40 % weerstand na negen maanden en nog maar 20 % na tien jaar bij onbeschermde ruiten. De VDW noemt vervangingstermijnen van twee jaar onbeschermd en twaalf jaar beschermd — de bindende termijn staat in je handleiding, het bouwjaar op het plaatje bij de ruit.",
    "bt.sichtscheibe.source": "Bron: DGUV/BGHM FBHM-040 over beschermruiten aan gereedschapsmachines, VDW-advies.",
    "bt.zink.title": "Verzinkte leidingen en tanks",
    "bt.zink.text": "Watermengbare concentraten tasten zink aan; coatings in de tank kunnen loslaten. Gebruik daarom geen verzinkt materiaal voor leidingen, tanks en opvangbakken. Ook een chloridegehalte boven 30 mg/l in het aanmaakwater leidt tot corrosie aan de machine.",
    "bt.zink.source": "Bron: FUCHS, toepassingsadviezen voor watermengbare koelsmeermiddelen.",
