    "pdf.disclaimer": "Let op: De hier beschikbare documenten (PDF) zijn afkomstig uit openbaar toegankelijke bronnen op internet (bijv. fabrikanten- en handelaarswebsites) en worden ongewijzigd als service weergegeven. Uitsluitend het actuele originele document van de fabrikant of leverancier is maatgevend. Wij geven geen garantie voor juistheid, volledigheid of actualiteit; aansprakelijkheid hiervoor is — voor zover wettelijk toegestaan — uitgesloten. Controleer veiligheidsrelevante gegevens altijd aan de hand van het actuele veiligheidsinformatieblad van uw leverancier.",
