    // Vertrouwenspagina (/vertrauen)
    "trust.title": "Zo bouwen we vertrouwen",
    "trust.intro1a": "In de handel tussen bedrijven tellen twee vragen: ",
    "trust.introQ1": "Met wie heb ik te maken?",
    "trust.intro1b": " En: ",
    "trust.introQ2": "Ben ik beschermd als er iets misgaat?",
    "trust.intro2": "Op beide geeft Brisco een duidelijk antwoord. Zo werkt het.",
    "trust.tiersTitle": "Verificatieniveaus",
    "trust.tiersText": "Elke reseller heeft een vertrouwensniveau. Het stijgt met geverifieerde identiteit, afgeronde deals en goede beoordelingen — en is overal zichtbaar.",
    "trust.reviewsTitle": "Beoordelingen die je niet kunt kopen",
    "trust.reviewsText": "Alleen wie via Brisco echt een deal heeft afgerond, kan een beoordeling geven. Elke ster hangt aan een echte transactie — niets gekocht, niets verzonnen. Gemiddelde en aantal staan open op elk profiel.",
    "trust.pseudoTitle": "Anoniem handelen, neutraal gesorteerd",
    "trust.pseudoText1": "Je treedt op onder een alias — je echte naam blijft verborgen. In berichten houdt een automatisch filter contactgegevens (e-mail, telefoon, links) tegen, zodat niemand je buiten het platform om afwerft.",
    "trust.pseudoText2a": "En de volgorde is eerlijk: betaalde plaatsingen zijn voor iedereen zichtbaar gemarkeerd als ",
    "trust.pseudoSponsored": "„Gesponsord”",
    "trust.pseudoText2b": ". Al het andere is neutraal gesorteerd.",
    "trust.docsTitle": "Alles gedocumenteerd",
    "trust.docsTextA": "Aanvraag, aanbieding, acceptatie en berichten lopen traceerbaar via het platform — niet in verspreide e-mails. Gaat er iets mis, dan is er een duidelijke weg om te reclameren. De regels staan in de ",
    "trust.protTitle": "Kopersbescherming: betalen zonder voor te schieten",
    "trust.protIntro": "Een vat hydraulische olie loopt snel in de vier cijfers, een IBC of pallet veel meer. Wie eerst overmaakt aan een onbekende handelaar draagt al het risico — en wie eerst levert, ook. Precies deze patstelling lost de kopersbescherming op.",
    "trust.howItWorks": "Zo verloopt het",
    "trust.step1t": "Jij betaalt — maar niet aan de verkoper",
    "trust.step1d": "Het bedrag gaat per kaart naar betaaldienst Stripe en blijft daar staan. De verkoper ziet dat er betaald is, maar krijgt geen cent.",
    "trust.step2t": "De verkoper levert",
    "trust.step2d": "Hij levert in de wetenschap dat het geld al vaststaat. Daarom levert hij ook aan kopers die hij niet kent.",
    "trust.step3t": "Jij bevestigt de ontvangst",
    "trust.step3d": "Pas deze klik geeft het geld vrij. Zonder die klik beweegt er niets — ook niet door de verkoper.",
    "trust.step4t": "Klopt er iets niet? „Probleem melden”",
    "trust.step4d": "In plaats van vrij te geven, meld je het probleem. Brisco beoordeelt en beslist over vrijgave of terugbetaling.",
    "trust.benefitsTitle": "Wat het jou oplevert",
    "trust.ben1t": "Geen vooruitbetaling aan een vreemde.",
    "trust.ben1d": " Je geld staat bij Stripe, niet bij de verkoper.",
    "trust.ben2t": "Jij houdt de sleutel.",
    "trust.ben2d": " Zonder jouw leveringsbevestiging wordt er niets uitbetaald.",
    "trust.ben3t": "Bij terugbetaling krijg je alles terug — ook de kosten.",
    "trust.ben3d": " Een probleemgeval mag jou niets kosten.",
    "trust.ben4t": "Handelen met onbekenden wordt mogelijk.",
    "trust.ben4d": " De beste prijs komt vaak van een handelaar met wie je nog nooit te maken had.",
    "trust.ben5t": "Alles gedocumenteerd.",
    "trust.ben5d": " Aanbieding, acceptatie, betaling en levering zijn traceerbaar op het platform — niet in verspreide e-mails.",
    "trust.costTitle": "Wat het kost",
    "trust.costText": "van het aankoopbedrag, gedragen door de koper. Bij € 2.000 is dat € 50,25. De kosten dekken de betaalafhandeling en de kopersbeschermingsdienst; een deel blijft als vergoeding bij Brisco. Word je terugbetaald, dan krijg je ook deze kosten terug.",
    "trust.limitsTitle": "Wat kopersbescherming niet is — zodat je goed beslist",
    "trust.lim1t": "Geen derdengeldenrekening en geen verzekering.",
    "trust.lim1d": " Brisco is geen bank. Het bedrag wordt gehouden bij de gereguleerde betaaldienst Stripe, niet op een rekening van Brisco.",
    "trust.lim2t": "Bij een geschil beslist Brisco",
    "trust.lim2d": " — op basis van de stukken, niet als rechtbank. De gang naar de rechter blijft je vrij.",
    "trust.lim3t": "Niet bij elke aanbieder beschikbaar.",
    "trust.lim3d": " Alleen wie het label „Kopersbescherming beschikbaar” draagt, heeft de uitbetaling ingesteld.",
    "trust.lim4t": "Het vervangt geen ingangscontrole van goederen.",
    "trust.lim4d": " Bevestig de levering pas nadat je hebt gecontroleerd — daarna is het geld bij de verkoper.",
    "trust.contractNote": "De contractuele details staan in ",
    "trust.contractLink": "§ 7 van de voorwaarden",
