    "ads.lockBody": "Als Merk-lid plaats je eigen banners op de advertentieplekken van het platform (startpagina, merk-showroom, aanbodoverzicht) — met eigen beeld, tekst, link en looptijd.",
    "ads.switchToMarke": "Overschakelen naar Merk",
    "ads.introBase": "Plaats banners op de advertentieplekken van het platform. Advertenties worden duidelijk als „advertentie“ gemarkeerd",
    "ads.introLinkedPre": "en zijn gekoppeld aan je merk",
