    "ghs.back": "Terug naar praktijkkennis",
    "ghs.subtitle": "De 9 officiële gevaarsymbolen op etiket en veiligheidsinformatieblad — eenvoudig uitgelegd",
    "ghs.introBefore": "Deze symbolen zijn EU-breed verplicht (CLP-verordening, onderdeel van het REACH-kader). Ze staan op elke verpakking en in",
    "ghs.introAfter": "Op onze productpagina's zie je ze direct in het VIB-kaartje — zo zie je in één oogopslag waarop je bij het gebruik moet letten.",
    "ghs.hSatze": "H-zinnen:",
    "ghs.countSingular": "In {count} veiligheidsinformatieblad in onze voorraad",
    "ghs.countPlural": "In {count} veiligheidsinformatiebladen in onze voorraad",
    "ghs.countNone": "Momenteel niet aanwezig in onze voorraad",
    "ghs.footnote1": "Let op: korte uitleg zonder aanspraak op volledigheid — bindend zijn het etiket en het veiligheidsinformatieblad van het betreffende product. Signaalwoorden:",
    "ghs.signalDanger": "„Gevaar“",
    "ghs.footnoteMid": "(ernstiger) resp.",
    "ghs.signalWarning": "„Waarschuwing“",
    "ghs.footnoteEnd": "(minder ernstig).",
    "ghs.s.GHS01.name": "Explosief",
    "ghs.s.GHS01.meaning": "De stof kan exploderen — door schok, wrijving, vonken of hitte.",
    "ghs.s.GHS01.praxis": "Bij oliën en koelsmeermiddelen vrijwel nooit; alleen relevant voor speciaalchemie.",
    "ghs.s.GHS02.name": "Ontvlambaar",
    "ghs.s.GHS02.meaning": "Vat gemakkelijk vlam — vonken of hete oppervlakken volstaan al.",
    "ghs.s.GHS02.praxis": "Belangrijk bij reinigers, verdunners en snijoliën met een laag vlampunt. Let op het vlampunt in het VIB.",
    "ghs.s.GHS03.name": "Oxiderend (brandbevorderend)",
    "ghs.s.GHS03.meaning": "Brandt zelf niet, maar wakkert branden sterk aan — levert zuurstof.",
    "ghs.s.GHS03.praxis": "Zelden bij smeermiddelen; eerder bij waterbehandelingschemie.",
    "ghs.s.GHS04.name": "Gassen onder druk",
    "ghs.s.GHS04.meaning": "Samengeperst of vloeibaar gemaakt gas — de houder kan barsten of vrieswonden veroorzaken.",
    "ghs.s.GHS04.praxis": "Betreft sprays/aerosolen, bijv. smeermiddel- en roestoplosser-sprays.",
    "ghs.s.GHS05.name": "Bijtend / corrosief",
    "ghs.s.GHS05.meaning": "Vernietigt huid en ogen bij contact; tast ook metalen aan.",
    "ghs.s.GHS05.praxis": "Voorzichtig met koelsmeermiddel-concentraten en systeemreinigers — draag handschoenen en een veiligheidsbril bij het aanmaken.",
    "ghs.s.GHS06.name": "Giftig (acuut toxisch)",
    "ghs.s.GHS06.meaning": "Zelfs kleine hoeveelheden kunnen ernstig schaden bij inademing, inslikken of huidcontact.",
    "ghs.s.GHS06.praxis": "Zeer zeldzaam bij moderne koelsmeermiddelen en oliën — komt het voor, ga dan bijzonder zorgvuldig met het product om.",
    "ghs.s.GHS07.name": "Irriterend / schadelijk",
    "ghs.s.GHS07.meaning": "Irriteert huid, ogen of luchtwegen; kan allergieën veroorzaken. Het mildste waarschuwingsniveau.",
    "ghs.s.GHS07.praxis": "Het meest voorkomende symbool bij koelsmeermiddelen — meestal door huidirritatie (H315) of sensibilisatie (H317). Beperk huidcontact en volg het onderhoudsplan.",
    "ghs.s.GHS08.name": "Gezondheidsgevaar (langdurig)",
    "ghs.s.GHS08.meaning": "Kan organen beschadigen, kanker veroorzaken of de vruchtbaarheid aantasten — vaak pas bij langdurig contact.",
    "ghs.s.GHS08.praxis": "Let op bij producten met H304 (kan bij inslikken in de longen terechtkomen) — typisch bij dunvloeibare oliën. Ook relevant voor TRGS 611-thema's (nitrosaminen).",
    "ghs.s.GHS09.name": "Milieugevaarlijk",
    "ghs.s.GHS09.meaning": "Giftig voor vissen en andere waterorganismen — mag niet in water of riolering terechtkomen.",
    "ghs.s.GHS09.praxis": "Belangrijk voor opslag (lekbak!) en afvoer: gebruikte emulsie en olie altijd als gevaarlijk afval afvoeren.",
